CENSUS_PIN = (481191, '11ada505c395ef6b94258981210bde4f116ce2c9c10843f11e7ad517f6eb9c8c')

def validate(c, selection, named, parent):
    rows = c['records']
    expected = sorted([r['entry'] for r in named['entries']], key=lambda x: int(x,16))
    assert len(rows) == len(expected) == len(set(expected)) == len(parent) == 208
    assert all(r['selected_outgoing_seed'] is True for r in named['entries'])
    assert named['seed_cap'] == 208 and 'ALL208' in named['policy']
    assert [r['entry'] for r in rows] == selection['entries'] == expected
    assert c['complete_frontier'] == dict(count=208, excluded_entries=[], scope='ALL208 selected; UI/render/control retained. Whole77clauses/194actualU unchanged.')
    assert c['selected_chunk_pins'] == EXPECTED_CHUNKS
    chunks = {q['path']: q for q in c['selected_chunk_pins']}
    ranges = collections.defaultdict(list)
    for r, n in zip(rows, sorted(named['entries'],key=lambda x: int(x['entry'],16))):
        line, old = parent[r['entry']]
        assert r['parent_alias_native_data_line'] == line == n['native_data_line']
        assert r['alias_record'] == old['record'] and r['alias_record']['name'] == n['name']
        assert r['alias_source'] == dict(path=old['provider'], line=old['source_line'], byte=old['source_byte'], bytes=old['raw_bytes'], sha256=old['raw_sha256'])
        assert r['alias_record']['external'] is False
        assert r['chunk_number'] == r['nonexternal_ordinal'] // 100
        assert Path(r['source_path']).name == f"chunk-{r['chunk_number']:05}.jsonl"
        chunk = chunks[r['source_path']]
        assert r['source_line'] > 0 and r['source_byte'] >= 0 and r['raw_bytes'] > 0
        assert r['source_byte'] + r['raw_bytes'] <= chunk['bytes']
        assert len(r['raw_sha256']) == len(r['code_sha256']) == 64 and 'code' not in r
        assert r['code_present'] and r['code_utf8_bytes'] > 0 and r['C_lines'] > 0
        assert r['partial_code'] is False and r['timed_out'] is False and r['error'] is None
        assert sum(int(b,16)-int(a,16)+1 for a,b in r['body_ranges']) == r['body_bytes'] > 0
        assert r['state'] == ('exported-with-warnings' if r['warnings'] else 'exported')
        assert stable(r) == RECORD_SEALS[r['entry']]
        ranges[r['source_path']].append((r['source_byte'],r['source_byte']+r['raw_bytes']))
    for rr in ranges.values():
        rr.sort()
        assert all(a[1]<=b[0] for a,b in zip(rr,rr[1:]))
    assert c['summary'] == EXPECTED_SUMMARY
    assert sum(r['code_utf8_bytes'] for r in rows) == 666796
    assert sum(r['C_lines'] for r in rows) == 15298
    assert max(r['C_lines'] for r in rows) == 395
    assert sum(bool(r['warnings']) for r in rows) == 6
    assert sum(len(r['warnings']) for r in rows) == 10
    assert sum(r['body_bytes']==4 for r in rows) == 76 and sum(r['thunk'] for r in rows) == 0
    assert c['source_caps_proposal'] == selection['proposed_source_caps'] == dict(records=208,C_bytes=2097152,C_lines=50000)
    assert c['source_semantics_selected'] is c['source_retention_selected'] is False
    assert c['new_callee_global_slot_native_image_provider_original_model_harness_follow'] == c['new_site_grade_case_release'] == 0
    assert c['required_unsupported'] == 'U' and c['coverage_gate'] == 'OPEN'
    assert c['alias_pass'] == dict(path='/var/tmp/sound-analysis/corpus/indexes/aliases.jsonl',bytes=122340555,lines=420470,sha256='6f05d75085ffb5f74826b4d44f3708fe89466b0b14581e538d912944f8167fcb',nonexternal_rows=418417,passes=1,stat_endpoints_equal=True)
    assert c['selection'] == dict(path=str(B/'reviews/legacy-whole208-root-metadata-selection.json'),bytes=6665,sha256='4f115c02a83176b55247196a4e88933e6b52c615b43350ca6b2fa3937587ee4e')
    assert len(c['predecessor_pins']) == 5
    expected_pins = [selection[k] for k in ['parent_manifest','parent_scope','parent_review','parent_seeds']]
    expected_pins.append(dict(path=str(B/'family-legacy-native-routes-v1/native-data.jsonl'),bytes=704486,sha256='b47511ea47cb7888deb302313bb4030c7ce75f412a1782b90b19a2f80f7a0029'))
    assert c['predecessor_pins'] == expected_pins
    assert c['class_inputs_pin'] == dict(path=str(B/'component-resolution-v1/class-inputs.json'),bytes=834035,sha256='47b807f450b33ad537eba9cd0e0e8e8346f5f65c973b6011ecef9012326414d0')
    assert c['successor'] == 'Separate Root coherent whole-source approval required; no retention/semantics/execution selected.'


def main():
    assert sys.argv[1:] == ['--check']
    raw = (P/'candidate-census.json').read_bytes()
    assert (len(raw),sha(raw)) == CENSUS_PIN
    c = json.loads(raw)
    raw = (P/'selection-metadata-only.json').read_bytes()
    assert (len(raw),sha(raw)) == (6665,'4f115c02a83176b55247196a4e88933e6b52c615b43350ca6b2fa3937587ee4e')
    selection=json.loads(raw)
    q=selection['parent_seeds'];raw=Path(q['path']).read_bytes()
    assert (len(raw),sha(raw)) == (q['bytes'],q['sha256'])
    named=json.loads(raw)
    path=B/'family-legacy-native-routes-v1/native-data.jsonl';raw=path.read_bytes()
    assert (len(raw),sha(raw)) == (704486,'b47511ea47cb7888deb302313bb4030c7ce75f412a1782b90b19a2f80f7a0029')
    parent={r['record']['entry']:(i,r) for i,r in enumerate(map(json.loads,raw.splitlines()),1) if r['kind']=='alias-data'}
    validate(c,selection,named,parent)
    negatives=[]
    def reject(name,change):
        bad=copy.deepcopy(c);change(bad)
        try:validate(bad,selection,named,parent)
        except (AssertionError,ValueError,KeyError,IndexError,TypeError):negatives.append(dict(name=name,rejected=True));return
        raise AssertionError('accepted mutation: '+name)
    warned=next(i for i,r in enumerate(c['records']) if r['warnings'])
    four=next(i for i,r in enumerate(c['records']) if r['body_bytes']==4)
    reject('drop-whole208-seed',lambda q:q['records'].pop())
    reject('duplicate-entry',lambda q:q['records'].__setitem__(1,q['records'][0]))
    reject('arbitrary-callee-substitution',lambda q:q['records'][0].update(entry='0xffff'))
    reject('reorder-same-complete-set',lambda q:q['records'].reverse())
    reject('wrong-alias-row',lambda q:q['records'][0]['alias_record'].update(name='other'))
    reject('wrong-parent-row',lambda q:q['records'][0].update(parent_alias_native_data_line=1))
    reject('wrong-alias-byte',lambda q:q['records'][0]['alias_source'].update(byte=0))
    reject('wrong-ordinal-chunk',lambda q:q['records'][0].update(chunk_number=0))
    reject('negative-export-offset',lambda q:q['records'][0].update(source_byte=-1))
    reject('export-beyond-chunk',lambda q:q['records'][0].update(raw_bytes=99999999))
    reject('retain-C',lambda q:q['records'][0].update(code='void f(){}'))
    reject('replace-C-hash',lambda q:q['records'][0].update(code_sha256='0'*64))
    reject('alter-C-size',lambda q:q['records'][0].update(code_utf8_bytes=0))
    reject('erase-warning',lambda q:q['records'][warned].update(warnings=[]))
    reject('rewrite-same-count-warning',lambda q:q['records'][warned]['warnings'].__setitem__(0,'replacement'))
    reject('repair-four-byte-extent',lambda q:q['records'][four].update(body_bytes=4096))
    reject('repair-thunk',lambda q:q['records'][four].update(thunk=True))
    reject('erase-error-metadata',lambda q:q['records'][0].pop('error'))
    reject('change-signature',lambda q:q['records'][0].update(signature='other'))
    reject('drop-chunk',lambda q:q['selected_chunk_pins'].pop())
    reject('rewrite-chunk-pin',lambda q:q['selected_chunk_pins'][0].update(sha256='0'*64))
    reject('exclude-UI-render',lambda q:q['complete_frontier']['excluded_entries'].append(q['records'][0]['entry']))
    reject('promote-source-read',lambda q:q.update(source_semantics_selected=True))
    reject('promote-source-retention',lambda q:q.update(source_retention_selected=True))
    reject('follow-callee',lambda q:q.update(new_callee_global_slot_native_image_provider_original_model_harness_follow=1))
    reject('absence-inference',lambda q:q['summary'].update(missing_is_absence_claim=True))
    reject('second-alias-pass',lambda q:q['alias_pass'].update(passes=2))
    reject('invent-grade-site',lambda q:q.update(new_site_grade_case_release=208))
    reject('close-coverage',lambda q:q.update(coverage_gate='CLOSED'))
    reject('invent-successor',lambda q:q.update(successor='run source now'))
    print(json.dumps(dict(status='PASS',metadata_records=208,C_utf8_bytes=666796,C_lines=15298,max_C_lines=395,warning_records=6,warning_occurrences=10,thunk_records=0,four_byte_extents=76,source_chunks=13,original_alias_passes_inherited=1,original_alias_chunk_source_native_image_provider_reads_by_checker=0,source_semantic_reads=0,source_retention=0,negative_count=len(negatives),negative_controls=negatives,coverage_gate='OPEN',required_unsupported='U',source_approval='Separate Root whole208 source decision required',record_seals='Exact metadata identity only; no C/native/source/runtime proof'),indent=2))

